import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"程序设计基础","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/程序设计基础.md","filePath":"专业基础/程序设计基础.md","lastUpdated":1792430298000}'),o={name:"专业基础/程序设计基础.md"};function l(n,t,i,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="程序设计基础" tabindex="-1">程序设计基础 <a class="header-anchor" href="#程序设计基础" aria-label="Permalink to &quot;程序设计基础&quot;">​</a></h1><blockquote><p>网安人的第一门手艺。校内对应「高级程序设计」（第 3 学期，C 语言）等课程。不会写程序，后面所有方向都走不远。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li><strong>C 语言</strong>：理解内存、指针、栈——这是 <a href="./../安全方向/二进制安全与逆向.html">二进制安全与逆向</a> 的起点；</li><li><strong>Python</strong>：写利用脚本（pwn）、自动化工具、数据分析的日常语言；</li><li>看懂代码是渗透、审计、逆向的最基础能力。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li><strong>C 语言</strong>为主线（校内课程 + 巩固），把指针、结构体、内存布局学透；</li><li><strong>Python</strong> 作为副线，做到「能写脚本」即可（requests、socket、pwntools 起步）；</li><li>逐步接触 Shell 脚本、SQL、正则（Web 安全必备）。</li></ol><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《C Primer Plus》</td><td>书</td><td>C 语言经典入门，适合零基础</td></tr><tr><td>《C 程序设计语言》（K&amp;R）</td><td>书</td><td>权威薄书，进阶必读</td></tr><tr><td>翁恺 C 语言（中国大学 MOOC，浙江大学）</td><td>公开课</td><td>中文口碑最好的 C 入门课</td></tr><tr><td><a href="https://docs.python.org/zh-cn/3/tutorial/" target="_blank" rel="noreferrer">Python 官方教程</a></td><td>文档</td><td>官方中文入门教程</td></tr><tr><td>CS50（Harvard，<a href="https://cs50.harvard.edu/x/" target="_blank" rel="noreferrer">cs50.harvard.edu</a>）</td><td>公开课</td><td>编程入门经典，作业体系完善</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>C 语言学完后，一定写点「窥探内存」的小程序（打印指针、观察栈布局），为逆向打底；</li><li>Python 不求系统学完，用到哪查到哪；</li><li>大二前的目标：<strong>能独立完成数据结构课程的编程作业，并读懂一段 C 的缓冲区溢出示例代码</strong>（仅在自己靶机上实验）。</li></ul>',10)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
